const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={needs:'Needs you',handled:'Handled',held:'Held',blocked:'Blocked',rejected:'Rejected',queued:'Queued',investigating:'Investigating',failed:'Could not verify'};
let state={events:[],rules:[],audit:[],jobs:[],notes:[],preferences:[],monitored:{events:[],jobs:[]}},page=location.hash.slice(1)||'home',filter='All',mode='autonomous',busy=false,correcting=null,loadError='';
let impactData=null,universeData=null,period=30,dataset='monitor',importRows=null;
const teachingText='You may automatically prepare Energy opportunity research consideration notes when both independent reviews clear, all hard policies pass, the proposed position is at most 3%, and resulting sector exposure is at most 20%. This never authorizes any orders.';
const brief=(s,n=240)=>s.length>n?s.slice(0,n-1)+'…':s;
const date=s=>s?new Date(s).toLocaleString():'Not recorded';
function notify(t){$('#toast').textContent=t;setTimeout(()=>$('#toast').textContent='',6000);}
function btn(text,action,cls='primary'){return `<button class="${cls}" data-action="${action}" ${busy?'disabled':''}>${text}</button>`;}
async function refresh(){if(page==='today'&&period===90)period=30;try{const r=await fetch('/api/state');if(!r.ok)throw Error('Unable to load workspace.');state=await r.json();if(page==='today')dataset=mode==='verified'?'replay':mode==='live'||state.events.some(e=>e.mode!=='verified')?'workspace':'monitor';const [ir,ur]=await Promise.all([fetch(`/api/impact?days=${period}&dataset=${dataset}`),fetch('/api/universe')]);if(ir.ok)impactData=await ir.json();if(ur.ok)universeData=await ur.json();loadError='';render();}catch(e){loadError=e.message;render();}}
async function command(action,fields={}){if(busy)return;busy=true;render();try{const r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify({action,...fields})});const result=await r.json();if(!r.ok)throw Error(result.error.replaceAll('_',' ').toLowerCase());await refresh();return result;}finally{busy=false;render();}}
function editorSymbols(){const p=state.portfolio||{holdings:[],watchlist:[]};return [...new Set([...p.holdings.map(h=>h.symbol),...p.watchlist])];}
function navigate(p){page=p;location.hash=p;render();window.scrollTo(0,0);}
function events(){if(mode==='verified')return state.events.filter(e=>e.mode==='verified');if(mode==='live')return state.events.filter(e=>e.mode!=='verified');const own=state.events.filter(e=>e.mode!=='verified');return own.length?own:state.monitored.events;}
const channelNames={google_news:'News search',press_wires:'Press releases',sec_edgar:'SEC filings',price_baseline:'Price baseline'};
function monitorHealth(){const w=state.watch;const healthy=w?.active&&Date.now()-Date.parse(w.checkedAt)<(w.intervalSeconds||300)*2500;return `<section class="monitor-health"><div><strong>${state.portfolio?.monitoring_enabled===false?'Your personal monitoring is paused':healthy?(w?.sourceErrors?.length?'Monitoring continues with source delays':'Watching for new developments'):w?.status||'Starting continuous monitoring'}</strong><p>Last successful news check: ${w?.lastSuccessAt?date(w.lastSuccessAt):w?.active?date(w.checkedAt):'Not verified yet'} · ${w?.symbols??'…'} securities observed · ${w?.intervalSeconds?Math.round(w.intervalSeconds/60):5}-minute news cadence</p><p>Material developments identified: ${state.operatingCounts?.source_material??'…'} · Investigations in progress: ${state.operatingCounts?.investigations??'…'} · Last meaningful activity: ${date(state.audit[0]?.at)}</p></div><details><summary>Monitoring coverage & health</summary><p>${esc(w?.source||'News monitoring starts independently of market sessions.')}</p><p>Last received source items: ${date(w?.lastReceivedAt)} · Deferred notices: ${w?.deferredNotices||0}</p><p>${esc(w?.coverageLimitations||'Headline search has bounded coverage; empty polls do not prove comprehensive coverage.')}</p>${w?.sourceErrors?.length?`<p>Delayed checks: ${esc(w.sourceErrors.join(', '))}</p>`:''}${Object.keys(w?.channels||{}).length?`<p>Sources: ${Object.entries(w.channels).map(([k,c])=>`${esc(channelNames[k]||k)} ${c.disabled?'off ('+esc((c.error||'').replaceAll('_',' ').toLowerCase())+')':c.ok?'ok':'failing for '+esc((c.failing||[]).join(', '))}`).join(' · ')}${w.scanSeconds!=null?` · last scan ${w.scanSeconds}s`:''}${w.waiting?` · ${w.waiting} waiting in line`:''}</p>`:''}${Object.entries(state.channels||{}).map(([k,c])=>`<p><strong>${esc(k)}</strong>: ${esc(c?.status||'Starting')}<br><small>${esc(c?.coverage||'')}</small></p>`).join('')}<p>Sources are polled under available permissions. Continuous operation requires the backend service to remain running. No guaranteed uptime or complete real-time coverage is claimed.</p></details></section>`;}
function modeBar(){return `<div class="mode-bar"><div class="mode-options" role="group" aria-label="Operating mode">${[['verified','Verified Run'],['live','Live Nemotron'],['autonomous','Autonomous']].map(([m,l])=>btn(l,'mode:'+m,m===mode?'primary':'secondary')).join('')}</div><p>${mode==='verified'?'Authentic captured NVIDIA Nemotron runs · historical replay in your isolated workspace.':mode==='live'?'Fresh NVIDIA Nemotron inference over preserved real evidence · results may differ from replay.':'Always-on event monitoring · fresh investigations when new information deserves attention · scheduled reviews maintain context.'}</p></div>`;}
function card(e,readonly=false){return `<article class="event ${e.status==='needs'?'attention':''}"><div class="event-top"><div class="ticker">${esc(e.symbol)}</div><div class="company"><strong>${esc(e.name)}</strong><span>${esc(e.kind)} · ${esc(e.session)}</span>${e.evidence.some(v=>v.text.startsWith('CONTROLLED ACCEPTANCE DELIVERY'))?'<small>Controlled source delivery · fresh AI</small>':''}</div><span class="pill ${e.status==='needs'?'needs':e.status==='blocked'?'blocked':''}">${labels[e.status]||esc(e.status)}</span></div><p>${esc(brief(e.summary))}</p>${e.explanation?`<small class="decision-stage">${esc(e.explanation.decision_right_label)} · ${esc(e.explanation.stage_label)}</small>`:''}${e.status==='needs'&&!readonly?`<div class="recommend"><span>RECOMMENDATION</span><strong>${e.kind==='Risk'?'Review and acknowledge this risk':'Prepare a research consideration note'}</strong><small>No order or brokerage authority</small></div><div class="actions">${e.kind==='Risk'?btn('Acknowledge risk','acknowledge:'+e.id):btn('Approve','approve:'+e.id)}${btn('Reject','reject:'+e.id,'secondary')}${btn('Correct & teach','correct:'+e.id,'text')}</div>`:''}${e.status==='needs'&&readonly&&mode==='autonomous'?btn('Review in my workspace','review-monitored:'+e.id,'secondary'):''}${e.ruleId?`<small>Approved rule ${esc(e.ruleId.slice(0,8))} · version ${e.rule_version}</small>`:''}${e.action?'<p><small>✓ Research note persisted and read back</small></p>':''}<button class="why" data-action="audit:${e.id}">View investigation <span>↗</span></button></article>`;}
function home(){return `<section class="hero"><div><div class="eyebrow"><i></i> YOUR MARKET, HANDLED</div><h1>You don’t have to<br>babysit the <em>market.</em></h1><p class="lead">MarketBell watches your portfolio, investigates what matters, and only asks you when a decision genuinely needs you.</p><div class="hero-actions">${btn('See MarketBell handle a market event →','demo')}<a href="#today">Explore today’s activity ↗</a></div><div class="hero-proof"><span>◉ Independent checks</span><span>▣ Rules control authority</span><span>↗ Learns with your approval</span></div></div><div class="hero-preview"><div class="preview-head"><span><i></i> MARKETBELL AT WORK</span><span>Authentic recorded runs</span></div><div class="preview-title">A little less market.<br>A little more life.</div><div class="mini-row"><b>✓</b><div><strong>Real evidence, independent judgement</strong><small>NVIDIA Nemotron on Nebius Token Factory.</small></div></div><div class="mini-row"><b>✓</b><div><strong>Hard rules always win</strong><small>No trading endpoints or execution authority.</small></div></div><div class="mini-decision"><span class="eyebrow">TEACH ONCE. HANDLE THE NEXT ONE.</span><h3>One decision. Less work next time.</h3><p>Review a real investigation. Teach a standing preference, then see whether the next company meets its conditions.</p>${btn('Make one decision →','demo')}</div><div class="preview-footer">AI understands the market. Rules control the money.</div></div></section><section class="steps"><div><span>01 / CONNECT</span><h3>Your investing world.</h3><p>Explore an isolated demo portfolio. Private account imports are disabled.</p></div><div><span>02 / TEACH</span><h3>Your judgement, remembered.</h3><p>Nemotron interprets your correction. You explicitly approve its proposed rule.</p></div><div><span>03 / LET GO</span><h3>Less work next time.</h3><p>Fresh checks determine whether your rule applies. Every outcome has a record.</p></div></section><section class="tech-band"><div><span class="eyebrow">POWERED BY NEBIUS × NVIDIA</span><h3>Reasoning where judgement matters.</h3><p>Independent Nemotron invocations interpret evidence and challenge it. Deterministic code controls every permitted action.</p></div><span class="pill">Replay · Fresh inference · Autonomous</span></section>`;}
function today(){const list=events(),needs=list.filter(e=>e.status==='needs'),done=list.filter(e=>!['needs','queued','investigating'].includes(e.status)&&(!impactData?.since||e.created>=impactData.since)),pending=list.filter(e=>['queued','investigating'].includes(e.status)),jobs=mode==='autonomous'?[...state.jobs,...state.monitored.jobs].slice(0,5):state.jobs;return `<div class="page-heading"><div><div class="eyebrow"><i></i> MARKETBELL IS WATCHING · DEMO PORTFOLIO</div><h1>${pending.length?'We’re looking into it.':needs.length?(needs.length===1?'One decision needs you.':needs.length+' decisions need you.'):list.length?'You’re caught up.':'Your market, handled.'}</h1><p class="brief">${esc(state.brief?.sentence||'Always watching for meaningful developments.')}</p><div class="actions">${btn('Ask MarketBell','ask-editor','secondary')}</div></div></div>${monitorHealth()}${operationsLine()}${answerCard()}${state.exposureIssues?.length?`<div class="notice"><strong>Portfolio limits need a look.</strong><p>${state.exposureIssues.map(esc).join(' ')}</p><a href="#portfolio">Review recorded allocations ↗</a></div>`:''}<details class="demo-controls"><summary>Demo controls · data source, recorded cases, workload numbers</summary>${modeBar()}${mode==='live'?`<p>${btn('Run fresh Nemotron on preserved evidence','start','secondary')}</p>`:''}${mode==='verified'?`<div class="actions">${btn('Independent check holds a case','case:challenge','secondary')}${btn('Policy prevents preparation','case:risk','secondary')}${btn('Routine review, no interruption','case:routine','secondary')}</div>`:''}${impactControls(false)}${impactMetrics()}<p>${btn('Restart workspace','restart','text')}</p></details>${jobs.some(j=>['queued','running'].includes(j.status))?'<div class="notice" role="status">Work is in progress. This page updates automatically; queued work is not counted as completed.</div>':''}${jobs.filter(j=>['failed','completed_with_errors'].includes(j.status)).map(j=>`<div class="notice">${esc(j.kind)} could not complete: ${esc(j.error)}. No unverified action taken. ${mode!=='autonomous'&&j.attempts<3?btn('Retry safely','retry:'+j.id,'text'):''}</div>`).join('')}${!list.length?`<div class="empty"><h3>${mode==='autonomous'?'Waiting for the worker’s first completed run.':'Give MarketBell one decision.'}</h3><p>${mode==='live'?'A real model call takes time. Recorded runs offer the fastest judge walkthrough.':'No synthetic verdicts. Start an authentic recorded investigation.'}</p>${mode!=='autonomous'?btn(mode==='verified'?'Start verified run →':'Run fresh Nemotron →','start'):''}</div>`:''}${mode!=='autonomous'&&state.rules.some(r=>r.active&&!r.revoked)&&!list.some(e=>e.recording==='vlo'||e.recording?.startsWith('vlo-live-'))?`<div class="learning-banner"><div><strong>Teach once. Handle the next one.</strong><p>Your rule is saved. The next company must clear both reviews and policy.</p></div>${btn('Run next similar event →','next')}</div>`:''}<div class="today-grid"><section><div class="section-heading"><h2>Needs you <span>${needs.length}</span></h2><small>Your judgement makes the difference.</small></div>${needs.length?needs.map(e=>card(e,mode==='autonomous'&&!state.events.some(v=>v.id===e.id))).join(''):'<div class="empty"><span>✓</span><h3>Nothing waiting on you.</h3><p>We’ll bring you decisions when your judgement is needed.</p></div>'}${pending.map(e=>card(e,true)).join('')}</section><section><div class="section-heading"><h2>Handled for you</h2><small>Quiet work. Clear outcomes.</small></div>${done.slice(0,8).map(e=>card(e,true)).join('')||'<p class="muted">Completed work will appear here.</p>'}</section></div>${quietPanel()}${learningPreview()}`;}
const quietLabels={WRONG_COMPANY:'Different company',AMBIGUOUS_NAME:'Ambiguous name',DUPLICATE:'Duplicate',BEFORE_MONITORING:'Before I was watching',COMMENTARY_ONLY:'Commentary only',ROUTINE_FILING:'Routine filing',OLD_NEWS:'Old news',NOT_REACHED:'Not reached in time'};
function quietPanel(){const q=(state.quiet||[]).filter(q=>q.followed).slice(0,8);return `<section class="quiet-log"><div class="section-heading"><h2>Why I stayed quiet <span>${state.brief?.setAside??0}</span></h2><small>Everything I read and set aside today, with the reason. Tell me if I got one wrong.</small></div>${q.length?q.map(i=>`<article class="event quiet-item"><div class="event-top"><div class="ticker">${esc(i.symbol)}</div><span class="pill">${esc(quietLabels[i.reason]||i.reason)}</span></div><h3>${esc(i.headline)}</h3><p>${esc(i.plain)}</p><small>${esc(i.publisher||'Unknown publisher')}${i.tier?' · '+(i.tier===1?'issuer or regulator':i.tier===2?'established newsroom':'commentary or unknown'):''} · ${date(i.published_at)}${i.source?` · <a href="${esc(i.source)}" target="_blank" rel="noopener noreferrer">source ↗</a>`:''}</small><div class="actions">${i.overturned?'<span class="pill">Marked important</span>':i.reason==='DUPLICATE'?'':btn('This mattered','overturn:'+i.id,'text')}</div></article>`).join(''):'<p class="muted">Nothing set aside yet for your holdings or watchlist.</p>'}</section>`;}
function answerCard(){const a=(state.answers||[])[0];if(!a)return '';return `<article class="event answer"><div class="eyebrow">YOU ASKED · ${date(a.at)}</div><h3>${esc(a.question)}</h3><p>${esc(a.answer)}</p>${a.uncertainty?`<small>${esc(a.uncertainty)}</small>`:''}<small>${a.mode==='model'?'Written by Nemotron from my records; every quote checked.':'From my records, no model call.'} ${(a.claims||[]).length} cited record(s). Never buy or sell advice.</small></article>`;}
function portfolio(){const p=state.portfolio;return `<div class="page-heading"><div><div class="eyebrow">YOUR INVESTING WORLD</div><h1>A portfolio with perspective.</h1><p>Isolated demo holdings and watchlist. No private account connected.</p><div class="actions">${btn('Portfolio & mandate setup','onboard','secondary')}${btn('Ask MarketBell to investigate','investigation-editor','text')} ${btn('Compare a candidate','compare-editor','text')}</div></div></div>${(state.exposureIssues||[]).map(t=>`<div class="notice"><strong>Portfolio boundary needs review</strong><p>${esc(t)}</p><small>Deterministic check of user-entered allocations; no trade or record change.</small></div>`).join('')}${universePanel()}<div class="portfolio-grid">${(p?[...p.holdings,...p.watchlist.map(symbol=>({symbol,position_pct:2}))]:[]).map(h=>{const e=[...state.events,...state.monitored.events].find(e=>e.symbol===h.symbol);return `<article class="portfolio-card"><div class="event-top"><div class="ticker">${esc(h.symbol)}</div><span class="pill">${e?labels[e.status]:'Watching'}</span></div><h3>${esc(e?.name||h.symbol)}</h3><p>${p.watchlist.includes(h.symbol)?'Watchlist · analytical scenario':p.name==='Manually maintained portfolio'?'User-entered holding':'Sample holding'} · ${h.position_pct}%</p><p>${e?esc(brief(e.summary,160)):'Waiting for an investigation.'}</p>${e?`<button class="why" data-action="audit:${e.id}">View investigation ↗</button>`:''}</article>`;}).join('')}</div>`;}
function activity(){const list=[...state.events,...state.monitored.events].filter(e=>filter==='All'||labels[e.status]===filter||e.kind===filter),logs=[...state.audit,...(state.monitored.audit||[])].sort((a,b)=>b.id-a.id).filter(a=>filter==='All'||filter==='User Decisions'&&a.type==='User decision'||filter==='Learned Preferences'&&/rule|Correction/.test(a.type));return `<div class="page-heading"><div><div class="eyebrow">EVERY OUTCOME HAS A RECORD</div><h1>Here’s what happened.</h1><p>Durable history, evidence references and verified actions. Timestamps use your local timezone.</p></div></div><div class="filters">${['All','Handled','Needs you','Opportunity','Risk','Routine','User Decisions','Learned Preferences'].map(f=>`<button class="${filter===f?'selected':''}" data-filter="${f}">${f}</button>`).join('')}</div><div class="timeline">${list.map(e=>`<div class="timeline-row"><span class="timeline-dot"></span><div><small>${esc(e.mode.toUpperCase())} · ${esc(e.session)} · ${date(e.resolved_at||e.created)}</small><h3>${esc(e.symbol)} · ${labels[e.status]}</h3><p>${esc(e.summary)}</p><button class="why" data-action="audit:${e.id}">View investigation ↗</button></div></div>`).join('')}${logs.map(a=>`<div class="timeline-row"><span class="timeline-dot real"></span><div><small>${date(a.at)} · AUDIT #${a.id}</small><h3>${esc(a.type)}</h3><p>${esc(a.detail)}</p><small>Record hash ${esc(a.hash.slice(0,18))}…</small></div></div>`).join('')}</div>`;}
function preferences(){return `<div class="page-heading"><div><div class="eyebrow">THE MORE YOU TEACH, THE LESS WE ASK</div><h1>A little more like you.</h1><p>You decide what becomes a rule. You can change your mind anytime.</p></div></div><div class="preference-layout"><section><div class="notice"><strong>Personal monitoring ${state.portfolio?.monitoring_enabled===false?'paused':'enabled'}</strong><p>New source investigations are checked against your portfolio and approved rules while this browser is closed.</p>${btn(state.portfolio?.monitoring_enabled===false?'Resume monitoring':'Pause monitoring','monitoring-toggle','secondary')}</div><h2>Standing rules</h2><p class="muted">Explicit permission, limited scope, expiry and revision history.</p>${state.rules.length?state.rules.map(r=>`<article class="event"><div class="event-top"><strong>${esc(r.sector)} research notes</strong><span class="pill">${r.revoked?'Revoked':!r.active?'Paused':new Date(r.expires)<new Date()?'Expired':'Active'} · v${r.version}</span></div><p>${esc(r.text)}</p><div class="rule-stats">Applied ${r.uses} time(s) · ${state.ruleStats?.find(s=>s.rule===r.id)?.nonmatches||0} recorded nonmatches · ${state.ruleStats?.find(s=>s.rule===r.id)?.exceptions||0} policy/review exceptions · Learned ${date(r.approved_at)}<br>Source: ${esc(r.source.slice(0,12))}<br>Last applied: ${date(r.lastApplied)}</div>${!r.revoked?`<div class="actions">${btn(r.active?'Pause':'Resume',(r.active?'pause:':'resume:')+r.id,'secondary')}${btn('Edit','edit:'+r.id,'text')}${btn('Revoke','revoke:'+r.id,'text')}</div>`:''}</article>`).join(''):`<div class="empty"><h3>Your first lesson starts with one decision.</h3><p>Choose “Correct & teach” on a decision that needs you, then review the proposed rule.</p>${btn('Teach MarketBell →','demo')}</div>`}${learningJournal()}<h2>Learned about you</h2>${state.preferences.length?state.preferences.map(p=>`<p>${esc(p.text)}</p><small>${esc(p.reason)}</small>`).join(''):'<p>No soft preferences saved yet.</p>'}<p><small>Context alone never grants authority.</small></p></section><aside class="boundary"><span class="eyebrow">YOUR AUTHORITY, IN ORDER</span><h3>AI interprets.<br>You set the boundaries.</h3><ol><li><strong>Hard system policy</strong><p>Position, sector, cash, freshness and evidence always win.</p></li><li><strong>Your approved rules</strong><p>Active, unexpired, matching rules only. Conflicts ask again.</p></li><li><strong>Soft preferences</strong><p>Context, never permission.</p></li><li><strong>Model recommendation</strong><p>A proposal, never authority.</p></li></ol><h4>We still ask about</h4><p>New scopes, conflicts and cases outside limits. Independent uncertainty holds the case.</p></aside></div>`;}
function impactControls(full=true){return `<div class="impact-controls"><label>Period<select id="impact-period">${(full?[1,7,30,90]:[1,7,30]).map(d=>`<option value="${d}" ${period===d?'selected':''}>${d===1?'Today':d+' days'}</option>`).join('')}</select></label>${full?`<label>History<select id="impact-dataset">${[['monitor','Public-source monitoring'],['workspace','My genuine workspace'],['replay','Verified replay'],['illustrative','Illustrative demo history']].map(([v,t])=>`<option value="${v}" ${dataset===v?'selected':''}>${t}</option>`).join('')}</select></label>`:''}${full&&dataset==='illustrative'?btn('Build illustrative history','impact-seed','secondary'):''}</div><p class="history-label">${esc(impactData?.label||'Loading durable history…')}</p>`;}
function impactMetrics(){if(!impactData)return '<div class="notice" role="status">Loading durable workload history…</div>';const c=impactData?.counts||{};return `<div class="summary impact-summary">${[['news_screened',impactData?.newsScreenedScope==='shared'?'news screened · shared':'news screened'],['material','material cases'],['autonomous','handled without you'],['attention','need attention'],['rule_reused','rule reuses']].map(([k,t])=>`<div><strong>${c[k]??0}</strong><span>${t}</span></div>`).join('')}</div><p class="muted">${c.autonomous||0} / ${c.developments||0} unique cases handled autonomously. Blocks, failures and unresolved cases stay in the denominator. ${impactData?.sufficientHistory?'':'Limited history; this period is not mature performance evidence.'}</p>`;}
function learningPreview(){return `<section class="recent-learning"><div class="section-heading"><h2>Recently learned</h2><a href="#preferences">Learning journal ↗</a></div>${[...state.rules].sort((a,b)=>Date.parse(b.approved_at)-Date.parse(a.approved_at)).slice(0,3).map(r=>`<article class="event"><strong>${esc(r.sector)} research notes</strong><p>${esc(r.text)}</p><small>${r.uses} valid applications · ${date(r.lastApplied)}</small></article>`).join('')||'<p class="muted">Your approved preferences and the decisions they influence will appear here.</p>'}</section>`;}
function listCandidateDialog(){const r=universeData?.list_candidate;if(!r)return;show(`<div class="eyebrow">REVIEW PROPOSED LIST AUTHORITY</div><h2>Approve this list-management rule?</h2><p>${esc(r.operation)} · ${esc(r.sector)} · ${esc(r.effect)} · watchlist cap ${r.max_watchlist} · ${r.expires_days} days</p><p>Independent reviews, hard policies, exclusions and pinned-company protection still apply. No ownership changes or trades.</p>${btn('Approve standing rule','list-approve:'+r.id)}`);}
function learningJournal(){const own=state.events.filter(e=>e.ruleId||e.rule_conflict);return `<h2>List-management lessons</h2>${universeData?.list_candidate?btn('Review proposed list rule','list-review','secondary'):''}${(universeData?.list_rules||[]).map(r=>`<article class="event"><strong>${esc(r.operation)} · ${esc(r.sector)}</strong><p>Watchlist cap ${r.max_watchlist} · ${esc(r.effect)} · ${r.uses} valid applications · ${r.active?'Active':'Paused / revoked'}</p><small>Last applied ${date(r.lastApplied)} · Expires ${date(r.expires)}</small>${!r.revoked?btn(r.active?'Pause':'Resume','list-'+(r.active?'pause:':'resume:')+r.id,'secondary')+btn('Edit','list-edit:'+r.id,'text')+btn('Revoke','list-revoke:'+r.id,'text'):''}</article>`).join('')}<h2>Learning journal</h2><p>A question avoided means one verified research note prepared under an active approved rule, without a case-specific decision. It is not measured time saved.</p>${own.map(e=>`<p><button class="why" data-action="audit:${e.id}">${esc(e.symbol)} · ${e.ruleId?'Applied '+esc(e.ruleId.slice(0,8)):'Rule conflict'} · ${date(e.resolved_at)}</button></p>`).join('')}<details><summary>Corrections, approvals, edits and revocations</summary>${state.audit.filter(a=>/rule|Correction|preference/.test(a.type)).slice(0,40).map(a=>`<p><strong>${esc(a.type)}</strong> · ${date(a.at)}<br>${esc(a.detail)}</p>`).join('')||'<p>No lessons recorded yet.</p>'}</details>`;}
function impact(){const d=impactData,c=d?.counts||{};return `<div class="page-heading"><div><div class="eyebrow">WORK DONE. LESSONS LEARNED. OUTCOMES REVIEWED.</div><h1>A little less work.<br>Full accountability.</h1><p>Research and permitted non-trading actions. No simulated investment returns.</p></div>${btn('Report a missed development','impact-report','secondary')}</div>${impactControls()}${impactMetrics()}<section class="impact-grid"><article class="event"><h2>What we absorbed</h2><p>${c.autonomous||0} cases handled without a case-specific decision; ${c.rule_reused||0} repeat approvals avoided through standing rules.</p><p>${c.user_involved||0} cases involved you. ${c.attention||0} still await a decision.</p><details><summary>Counting definitions</summary>${Object.entries(d?.definitions||{}).map(([k,v])=>`<p><strong>${esc(k.replaceAll('_',' '))}</strong>: ${esc(v)}</p>`).join('')}</details></article><article class="event"><h2>What needs improvement</h2><p>${c.blocked||0} policy blocks · ${c.unresolved||0} unresolved, held or unfinished cases · ${d?.failures?.disagreements||0} Research/Challenge disagreements.</p><p>Misses and false alerts include user reports; incomplete news sources cannot reveal every missed event.</p><details><summary>Reports and limitations</summary>${(d?.reports||[]).map(r=>`<p><strong>${esc(r.kind.replaceAll('_',' '))}</strong>: ${esc(r.text)}<br><small>${esc(r.attribution)}</small></p>`).join('')||'<p>No user reports in this view. This does not prove there were no misses.</p>'}</details></article></section><section class="event"><h2>Opportunities managed within your authority</h2><p>${d?.universe?.discovered||0} companies discovered · ${d?.universe?.automatically_organized||0} automatic list changes · ${d?.universe?.automatically_archived||0} automatically archived · ${d?.universe?.learned_applications||0} learned list-rule applications.</p><p>These are list actions, separate from fully handled cases and note approvals avoided. No ownership or exposure changes.</p><details><summary>Promotions, demotions and portfolio proposals</summary>${(d?.universe?.operations||[]).map(r=>`<p>${esc(r.action.replaceAll('_',' '))} · ${esc(r.status)} · ${r.count}</p>`).join('')||'<p>No universe changes in this history.</p>'}</details><details><summary>Were promoted and rejected candidates useful?</summary>${(d?.candidateComparisons||[]).map(r=>`<p>${esc(r.action)} · ${esc(r.disposition)} · ${esc(r.outcome)} · ${r.horizon_reviews} horizon review(s)</p>`).join('')||'<p>Not enough later evidence to compare these cohorts.</p>'}<p>These assessments concern original qualitative theses; they are not simulated investment returns or a causal test of selection skill.</p></details></section><section><h2>Autonomy over time</h2>${(d?.weeks||[]).length>=2?`<div class="weekly-history">${d.weeks.map(w=>`<div><strong>${esc(w.week)}</strong><meter aria-label="${esc(w.week)}: ${w.autonomous} of ${w.cases} autonomous cases" min="0" max="${Math.max(1,w.cases)}" value="${w.autonomous}">${w.autonomous}/${w.cases}</meter><small>${w.autonomous}/${w.cases} autonomous · ${w.attention} need attention · ${w.rules} rules · ${w.unresolved} unresolved</small></div>`).join('')}</div>`:'<p class="muted">At least two recorded weeks are needed to show a trend. Higher automation alone does not establish better outcomes.</p>'}</section><section><h2>Original rationale & later evidence</h2>${Object.values(d?.snapshots||{}).sort((a,b)=>Number((d.evaluations||[]).some(e=>e.event===b.event))-Number((d.evaluations||[]).some(e=>e.event===a.event))).slice(0,10).map(s=>{const reviews=(d.evaluations||[]).filter(e=>e.event===s.event);return `<details class="event"><summary>${esc(s.symbol)} · ${date(s.at)} · ${reviews.length?'Follow-up recorded':'Awaiting 7 / 30 / 90-day review'}</summary><div class="comparison"><div><h3>Original, preserved</h3><p>${esc(s.rationale)}</p><p>${esc(s.research.summary)}</p><p><strong>Challenge:</strong> ${esc(s.challenge.summary)}</p><p>${esc(s.hypothesis)}</p><small>${esc(s.uncertainty)}</small></div><div><h3>Later assessment</h3>${reviews.map(e=>`<p><strong>${e.horizon_days} days · ${esc(e.outcome.replaceAll('_',' '))}</strong><br>${esc(e.thesis_quality)}<br><small>${esc(e.market_performance.reason)}</small></p>${e.later_evidence.map(v=>`<p>${esc(v.text)}<br><small>${date(v.published_at)}</small></p>`).join('')}`).join('')||'<p>Still awaiting review. No outcome has been inferred.</p>'}</div></div></details>`;}).join('')||'<p>No original decisions in this history yet.</p>'}</section><section><h2>Recent cases</h2>${(d?.cases||[]).map(e=>`<article class="event"><strong>${esc(e.symbol)} · ${esc(labels[e.status]||e.status)}</strong><p>${esc(e.summary)}</p>${btn('Open durable history','impact-case:'+e.id,'text')}</article>`).join('')}${d?.nextOffset!==null&&d?.nextOffset!==undefined?btn('Next 20 cases','impact-more','secondary'):''}</section>`;}
function universePanel(){const u=universeData;return `<section><h2>Your investment universe</h2><p>${esc(u?.coverage||'Loading…')} Manual holdings are user-entered and not verified by a brokerage.</p><div class="universe-tiers">${['portfolio','watchlist','pool'].map(t=>`<article class="event"><h3>${t==='pool'?'Opportunity pool':t[0].toUpperCase()+t.slice(1)}</h3>${(u?.entries||[]).filter(e=>e.tier===t).map(e=>`<p><strong>${esc(e.symbol)}</strong> ${e.pinned?'· Pinned':''}<br><small>${esc(e.ownership||'Research candidate; no ownership')} ${e.priority==='low'?'· Lower priority':''}</small>${t!=='portfolio'&&!e.pinned?btn('Archive','archive:'+e.symbol,'text'):''}</p>`).join('')||'<p class="muted">No companies yet.</p>'}</article>`).join('')}</div><details><summary>Mandate and decision rights</summary><p>${esc(u?.mandate.objective)}</p><p>Mandate baseline automation: ${Object.entries(u?.mandate.automatic||{}).filter(([,v])=>v).map(([k])=>esc(k)).join(', ')||'No list changes delegated'}. Active learned list rules in Preferences may add or restrict non-trading list rights. Portfolio proposals always ask. Brokerage execution, ownership changes by the agent and policy overrides are prohibited.</p><p>Position ≤ ${u?.mandate.max_position_pct}% · Sector ≤ ${u?.mandate.max_sector_pct}% · Watchlist ≤ ${u?.mandate.max_watchlist}</p></details><h3>Recommendations & list decisions</h3>${(u?.recommendations||[]).slice(0,8).map(r=>`<article class="event"><strong>${esc(r.symbol)} · ${esc(r.action.replaceAll('_',' '))}</strong><span class="pill">${esc(r.status)}</span><p>${esc(r.reason)}</p><p><small>${esc(r.authority)} · No ownership change or trade.</small></p>${r.status==='proposed'?`${btn('Confirm recommendation','universe-approve:'+r.id)} ${btn('Reject','universe-reject:'+r.id,'secondary')} ${btn('Correct & teach','list-correct:'+r.id,'text')}`:''}</article>`).join('')||'<p>News investigations will produce evidence-backed candidate decisions here.</p>'}<details><summary>Universe change history</summary>${(u?.history||[]).slice(0,25).map(h=>`<p>${date(h.at)} · ${esc(h.kind)} · ${esc(h.symbol||'Mandate / entries')}</p>`).join('')}</details></section>`;}
function onboarding(){const m=universeData.mandate;show(`<div class="eyebrow">REVIEW BEFORE SAVING</div><h2>Your holdings, watchlist & mandate</h2><p>User-entered records only. Provide quantity for holdings and allocation % for exposure checks. A zero allocation is unknown and cannot authorize a research note. Supported exchanges: XNAS / XNYS; 32-company curated catalog.</p><details><summary>Add a company manually</summary><label>Company<select id="manual-symbol">${universeData.catalog.map(c=>`<option value="${c.symbol}">${esc(c.symbol+' · '+c.name)}</option>`).join('')}</select></label><label>Tier<select id="manual-tier"><option value="watchlist">Watchlist — not owned</option><option value="portfolio">Recorded holding — user entered</option></select></label><div class="form-pair"><label>Shares<input id="manual-quantity" type="number" min="0" value="0"></label><label>Optional cost basis per share<input id="manual-cost" type="number" min="0"></label><label>Allocation % (0 means unknown)<input id="manual-allocation" type="number" min="0" max="100" value="0"></label></div><label class="check-label"><input id="manual-pin" type="checkbox"> Keep this company under observation</label>${btn('Add to draft entries','manual-add','secondary')}</details><label>Holdings and watchlist CSV<textarea id="universe-csv" maxlength="20000" rows="6" placeholder="ticker,exchange,tier,quantity,cost_basis,position_pct,horizon,pinned
PSX,XNYS,watchlist,0,,0,long_term,true"></textarea></label><label>Or choose CSV file<input id="universe-file" type="file" accept=".csv,text/csv"></label><details><summary>Supported company catalog</summary><p>${universeData.catalog.map(c=>esc(c.symbol+' ('+c.exchange+')')).join(' · ')}</p></details><label>Objective<textarea id="mandate-objective">${esc(m.objective)}</textarea></label><label>Horizon<select id="mandate-horizon">${['short_term','medium_term','long_term'].map(h=>`<option ${h===m.horizon?'selected':''}>${h}</option>`).join('')}</select></label><label>Excluded symbols (comma separated)<input id="mandate-exclusions" value="${esc(m.excluded_symbols.join(','))}"></label><label>Excluded sectors (comma separated)<input id="mandate-sectors" value="${esc(m.excluded_sectors.join(','))}"></label><div class="form-pair"><label>Max position %<input id="mandate-position" type="number" min="0.1" max="5" step="0.1" value="${m.max_position_pct}"></label><label>Max sector %<input id="mandate-sector" type="number" min="1" max="30" value="${m.max_sector_pct}"></label><label>Max watchlist<input id="mandate-watch" type="number" min="1" max="30" value="${m.max_watchlist}"></label><label>Cash allocation %<input id="mandate-cash" type="number" min="0" max="100" value="${state.portfolio.cash_pct}"></label></div><fieldset><legend>Explicit non-trading delegation</legend>${['promote','deprioritize','archive'].map(k=>`<label class="check-label"><input type="checkbox" id="authority-${k}" ${m.automatic[k]?'checked':''}> Allow ${k} of eligible unpinned research candidates within this mandate</label>`).join('')}</fieldset><div id="universe-review"></div>${btn('Validate & preview entries','universe-preview')} ${btn('Review mandate only','mandate-review','secondary')}`);}
function render(){if(!['home','today','portfolio','impact','activity','preferences'].includes(page))page='today';$('#app').innerHTML=`<header><a class="brand" href="#home"><span class="bell">♧</span>marketbell<span class="brand-dot">.</span></a><nav aria-label="Main navigation">${['today','portfolio','impact','activity','preferences'].map(p=>`<a class="${page===p?'active':''}" href="#${p}">${p[0].toUpperCase()+p.slice(1)}</a>`).join('')}</nav><span class="demo-tag">ISOLATED DEMO WORKSPACE</span></header><main>${loadError?`<div class="notice" role="alert">${esc(loadError)} ${btn('Try again','refresh','text')}</div>`:''}${({home,today,portfolio,impact,activity,preferences})[page]()}</main><footer><a class="brand" href="#home">marketbell.</a><span>Real evidence · Demo portfolio · No orders · Private imports disabled</span><a href="#preferences">Your rules. Your call. ↗</a></footer>`;}
function show(html){const d=$('#modal');d.innerHTML=`<button class="close" data-action="close" aria-label="Close dialog">×</button>${html}`;if(!d.open)d.showModal();d.querySelector('input,textarea,button:not(.close)')?.focus();}
function candidateDialog(){const c=state.candidate;if(c)show(`<div class="eyebrow">REVIEW PROPOSED AUTHORITY</div><h2>Save this standing preference?</h2><p>${esc(c.text)}</p><ul class="checks"><li>✓ Both independent reviews must clear</li><li>✓ Hard policy rechecked for every action</li><li>✓ Research notes only · never orders</li><li>✓ Expiry and revocation enforced</li></ul><p>Saving grants the standing rule only. The current case still needs your separate decision.</p>${btn('Save preference','save-rule:'+c.id)} ${btn('Keep asking me','decline-rule','text')}`);}
function explanationBlock(e){const x=e.explanation;if(!x)return '';const tag=k=>`<em class="tag">${k==='observed'?'Observed':'AI interpretation'}</em>`;const row=(t,v)=>v?`<dt>${t}</dt><dd>${v}</dd>`:'';if(x.level==='brief')return `<dl class="decision-summary">${row('What happened',tag('observed')+' '+esc(x.what_happened.text))}${row('Decision',`<strong>${esc(x.decision_right_label)}</strong> · ${esc(x.stage_label)}<br>${esc(x.why_authority)}`)}</dl>`;const ev=x.evidence||{};return `<dl class="decision-summary">${row('What happened',tag('observed')+' '+esc(x.what_happened.text))}${x.why_it_matters?row('Why it matters',tag('model_interpretation')+' '+esc(x.why_it_matters.text)):''}${row('Evidence',`${(ev.items||[]).length} item(s) · cited sources ${esc(ev.cited_freshness)}${ev.price_baseline?' · price baseline '+esc(ev.price_baseline):''}${ev.sufficiency?'<br>'+esc(ev.sufficiency):''}`)}${x.uncertainty?row('Uncertainty',tag('model_interpretation')+' '+esc(x.uncertainty.text)):''}${row('Downside and limits',[...(x.downside||[]).map(d=>(d.kind==='policy'?'':tag('model_interpretation')+' ')+esc(d.text)),...(x.cautions||[]).map(esc)].join('<br>'))}${row('Your rules',(x.rules||[]).map(esc).join('<br>'))}${row('Proposed action',esc(x.proposed_action))}${row('Decision',`<strong>${esc(x.decision_right_label)}</strong> · ${esc(x.stage_label)}<br>${esc(x.why_authority)}`)}${row('Check later',esc(x.outcome_to_check))}</dl><p class="muted"><small>${esc(x.note)}</small></p>`}
function operationsLine(){const o=state.operations;if(!o)return '';const items=[['Handled without you',o.handled_without_you],['Under your rules',o.under_standing_rule],['Needs you',o.needs_you],['Decided by you',o.decided_by_you],['Blocked',o.blocked],['Monitoring',o.monitoring],['Awaiting evidence',o.awaiting_evidence],['Not verified',o.not_verified],['Outcomes reviewed',o.verified_outcomes]];return `<p class="operations-line" aria-label="Recorded case counts">${items.map(([l,n])=>`<span>${l} <b>${n}</b></span>`).join('')}</p>`}
function investigation(id){const e=[...state.events,...state.monitored.events].find(e=>e.id===id);if(!e)return;show(`<div class="eyebrow">INVESTIGATION / ${esc(e.symbol)}</div><h2>Every outcome, explained.</h2>${e.portfolio_basis?`<p class="muted">${esc(e.portfolio_basis)}</p>`:''}<span class="pill">${esc(e.mode)} · ${esc(e.session)}</span>${explanationBlock(e)}<dl><dt>Trigger</dt><dd>${esc(e.trigger)}</dd><dt>Research</dt><dd>${esc(e.research?.summary||'Not completed')}</dd><dt>Blind independent challenge</dt><dd>${esc(e.challenge?.summary||'Not completed')}<br>No Research conclusion supplied in the Challenge request.</dd><dt>Resolution</dt><dd>${esc(e.resolution?.method||'Pending')}</dd><dt>Deterministic policy</dt><dd>${e.policy?Object.entries(e.policy).map(([k,v])=>`${v?'✓':'✕'} ${esc(k.replaceAll('_',' '))}`).join('<br>'):'Not evaluated'}</dd><dt>Action / readback</dt><dd>${esc(e.summary)}<br>${e.action?`Verified note hash: ${esc(e.action.hash)}`:'No preparation action completed.'}</dd>${state.notes?.find(n=>n.id===e.action?.id)?`<dt>Prepared research note</dt><dd><details><summary>Read the persisted consideration note</summary><h3>${esc(e.symbol)} · Research consideration</h3><p>${esc(state.notes.find(n=>n.id===e.action.id).research.summary)}</p><p><strong>Independent check:</strong> ${esc(state.notes.find(n=>n.id===e.action.id).challenge.summary)}</p><p>${esc(state.notes.find(n=>n.id===e.action.id).limitations)}</p><small>Verified note ${esc(e.action.hash)}</small></details></dd>`:''}<dt>AI runtime</dt><dd>NVIDIA ${esc(state.model)} · Nebius Token Factory<br>${e.mode==='verified'?'Authentic historical replay; no fresh inference.':e.shared_investigation?'Source investigation reused for identical evidence; your current portfolio policy and authority evaluated separately.':'Fresh model calls recorded with timestamp and request hash.'}</dd><dt>Evidence and provenance</dt><dd>${e.evidence.map(v=>`<div class="source"><strong>${esc(v.type)}</strong><br>${v.source.startsWith('https://')?`<a href="${esc(v.source)}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:esc(v.source)}<br>Retrieved ${date(v.retrieved_at)}<br>${esc(v.limitation||'')}<br><code>${esc(v.id)}</code><details><summary>Read preserved evidence</summary><p>${esc(v.text)}</p></details></div>`).join('')}</dd><dt>Cited claims</dt><dd>${['research','challenge'].map(k=>(e[k]?.claims||[]).map(c=>`<p>${esc(k)} · ${esc(c.evidence_id.slice(0,12))}<br>“${esc(c.quote)}”</p>`).join('')).join('')}</dd></dl>`);}
document.addEventListener('click',async e=>{const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();return;}const b=e.target.closest('[data-action]');if(!b)return;const [action,id]=b.dataset.action.split(':');try{
if(action==='compare-editor'){show(`<h2>Compare with a holding</h2><p>Fresh Research and blind Challenge examine both source packages. A replacement proposal still requires your confirmation; ownership cannot change.</p><label>Candidate<select id="compare-candidate">${universeData.catalog.map(c=>`<option>${esc(c.symbol)}</option>`).join('')}</select></label><label>Existing holding<select id="compare-holding">${state.portfolio.holdings.map(h=>`<option>${esc(h.symbol)}</option>`).join('')}</select></label>${btn('Run independent comparison','compare-submit')}`);return;}
if(action==='compare-submit'){await command('compare-candidates',{candidate:$('#compare-candidate').value,holding:$('#compare-holding').value});$('#modal').close();mode='live';navigate('today');return;}
if(action==='list-correct'){correcting=id;show(`<h2>Teach list management</h2><p>Nemotron proposes a limited rule. It grants no authority until you review and approve it. No ownership or trading permission can be delegated.</p><label>Your correction<textarea id="list-correction" maxlength="1000">You may promote Energy research candidates to my watchlist when both independent reviews clear and all policies pass, with at most 12 watchlist companies, for 30 days.</textarea></label>${btn('Propose a rule','list-propose')}`);return;}
if(action==='list-propose'){const text=$('#list-correction').value;await command('list-correct',{id:correcting,text});$('#modal').close();notify('Nemotron is interpreting the correction in the background. No authority granted.');return;}
if(action==='list-review'){listCandidateDialog();return;}
if(action==='list-edit'){const r=universeData.list_rules.find(r=>r.id===id);show(`<h2>Edit list-management rule</h2><p>Scope remains ${esc(r.operation)} · ${esc(r.sector)}. Saving explicitly approves the revised authority.</p><label>Watchlist cap<input id="list-cap" type="number" min="1" max="30" value="${r.max_watchlist}"></label><label>Authority<select id="list-effect"><option value="allow" ${r.effect==='allow'?'selected':''}>Automatic within all checks</option><option value="ask" ${r.effect==='ask'?'selected':''}>Prepare and ask</option></select></label>${btn('Approve updated rule','list-update:'+r.id)}`);return;}
if(action==='list-update'){const r=universeData.list_rules.find(r=>r.id===id);await command('list-rule',{id,operation:'edit',version:r.version,updates:{max_watchlist:Number($('#list-cap').value),effect:$('#list-effect').value}});$('#modal').close();return;}
if(['list-approve','list-pause','list-resume','list-revoke'].includes(action)){const r=universeData.list_rules.find(r=>r.id===id);await command('list-rule',{id,operation:action.slice(5),version:r?.version});$('#modal').close();notify('List authority decision recorded.');return;}
if(action==='impact-seed'){await command('impact-demo');await refresh();return;}
if(action==='impact-more'){const r=await fetch(`/api/impact?days=${period}&dataset=${dataset}&offset=${impactData.nextOffset}`);if(!r.ok)throw Error('History unavailable');impactData=await r.json();render();return;}
if(action==='impact-case'){const response=await fetch(`/api/impact-event?dataset=${dataset}&id=${encodeURIComponent(id)}`);if(!response.ok)throw Error('This investigation is unavailable in the selected workspace.');const record=await response.json();const e=record.event;show(`<div class="eyebrow">${esc(impactData.label)}</div><h2>${esc(e.symbol)} · Every outcome, explained</h2><p>${esc(e.summary)}</p><h3>Original rationale</h3><p>${esc(record.snapshot?.rationale||'No verified original decision yet.')}</p><p><strong>Research:</strong> ${esc(e.research?.summary||'Incomplete')}</p><p><strong>Independent Challenge:</strong> ${esc(e.challenge?.summary||'Incomplete')}</p><h3>Later reviews</h3>${record.evaluations.map(v=>`<p>${v.horizon_days} days · ${esc(v.outcome)}<br>${esc(v.thesis_quality)}</p>`).join('')||'<p>Awaiting review; no result inferred.</p>'}<h3>Evidence</h3>${e.evidence.map(v=>`<details><summary>${esc(v.type)} · ${date(v.published_at||v.retrieved_at)}</summary><p>${esc(v.text)}</p><p>${esc(v.source)}</p></details>`).join('')}<h3>Durable lifecycle</h3>${record.trail.map(l=>`<details><summary>${esc(l.stage)} · ${date(l.at)}</summary><pre>${esc(JSON.stringify(JSON.parse(l.body),null,2))}</pre></details>`).join('')}`);return;}
if(action==='impact-report'){show(`<h2>Help us see what we missed</h2><p>Your report is attributed feedback, not an independently verified finding.</p><label>Type<select id="feedback-kind">${['missed_risk','missed_opportunity','wrong_ticker','false_alert','unsupported_conclusion','useful','not_useful'].map(k=>`<option>${k}</option>`).join('')}</select></label><label>What happened?<textarea id="feedback-text" maxlength="1000"></textarea></label>${btn('Save report','feedback-save')}`);return;}
if(action==='feedback-save'){await command('impact-feedback',{kind:$('#feedback-kind').value,text:$('#feedback-text').value});$('#modal').close();dataset='workspace';await refresh();notify('Feedback saved in your workspace.');return;}
if(action==='manual-add'){const symbol=$('#manual-symbol').value,c=universeData.catalog.find(c=>c.symbol===symbol);const row=[symbol,c.exchange,$('#manual-tier').value,$('#manual-quantity').value,$('#manual-cost').value,$('#manual-allocation').value,'long_term',$('#manual-pin').checked];const field=$('#universe-csv');field.value=(field.value.trim()||'ticker,exchange,tier,quantity,cost_basis,position_pct,horizon,pinned')+'\n'+row.join(',');notify('Added to draft. Validate and review before saving.');return;}
if(action==='onboard'){onboarding();return;}
if(action==='universe-preview'||action==='mandate-review'){if(action==='universe-preview'){const file=$('#universe-file').files[0];const csv=file?await file.text():$('#universe-csv').value;const result=await command('universe-preview',{csv});importRows=result.rows;}else{importRows=universeData.entries.filter(e=>['portfolio','watchlist'].includes(e.tier)).map(e=>({...e,ticker:e.symbol,quantity:e.quantity||0,horizon:e.horizon||'long_term'}));if(importRows.some(e=>e.tier==='portfolio'&&!e.quantity))throw Error('Enter quantities for existing illustrative holdings using the CSV review first.');}$('#universe-review').innerHTML=`<h3>Confirm ${importRows.length} entries</h3><p>${importRows.map(r=>esc(r.symbol+' · '+r.tier+' · '+r.quantity+' shares · '+r.position_pct+'%')).join('<br>')}</p><p>Saving replaces the active manually maintained holdings/watchlist and confirms the displayed mandate. It records no trade. Existing learned list rules for unchecked operations will be paused.</p>${btn('Confirm entries & authority','universe-confirm')}`;return;}
if(action==='universe-confirm'){const split=s=>s.split(',').map(v=>v.trim()).filter(Boolean);const mandate={objective:$('#mandate-objective').value,horizon:$('#mandate-horizon').value,excluded_symbols:split($('#mandate-exclusions').value),excluded_sectors:split($('#mandate-sectors').value),max_position_pct:Number($('#mandate-position').value),max_sector_pct:Number($('#mandate-sector').value),max_watchlist:Number($('#mandate-watch').value),automatic:Object.fromEntries(['promote','deprioritize','archive'].map(k=>[k,$('#authority-'+k).checked]))};await command('universe-commit',{rows:importRows,mandate,version:state.portfolio.version,confirmed:true,cash_pct:Number($('#mandate-cash').value)});$('#modal').close();notify('Entries and mandate confirmed. No trade placed.');return;}
if(action==='archive'){await command('universe-archive',{symbol:id,version:state.portfolio.version,confirmed:true});notify('Candidate archived; pinned companies and holdings remain protected.');return;}
if(action==='universe-approve'||action==='universe-reject'){const r=universeData.recommendations.find(r=>r.id===id);await command('universe-decision',{id,version:r.version,choice:action==='universe-approve'?'approve':'reject'});notify('Recommendation decision recorded. No ownership changed.');return;}
if(action==='close')return $('#modal').close();if(action==='refresh')return refresh();if(action==='monitoring-toggle'){await command(action,{enabled:state.portfolio?.monitoring_enabled===false});return;}if(action==='mode'){mode=id;return refresh();}
if(action==='demo'){mode='verified';dataset='replay';navigate('today');if(!events().length)await command('start',{mode});return;}
if(action==='start'||action==='next'){if(mode==='live'&&!state.liveEnabled)throw Error('Fresh inference is disabled here. Verified replay remains available.');await command(action,{mode});return;}
if(action==='portfolio-editor'){show(`<h2>Your demo investing world</h2><p>Illustrative holdings only. Zero keeps a security on the watchlist. No account is connected.</p>${editorSymbols().map(symbol=>`<label>${esc(symbol)} position (%)<input id="holding-${esc(symbol)}" type="number" min="0" max="100" step="0.1" value="${state.portfolio.holdings.find(h=>h.symbol===symbol)?.position_pct||0}"></label>`).join('')}<label>Available cash (%)<input id="portfolio-cash" type="number" min="0" max="100" value="${state.portfolio.cash_pct}"></label>${btn('Save & review changes','portfolio-save')}`);return;}
if(action==='portfolio-save'){const holdings=editorSymbols().map(symbol=>({symbol,position_pct:Number($('#holding-'+symbol).value)})).filter(h=>h.position_pct!==0),cash_pct=Number($('#portfolio-cash').value);await command('portfolio-update',{holdings,cash_pct,version:state.portfolio.version});$('#modal').close();notify('Demo holdings saved. Changed holdings are queued for review.');return;}
if(action==='investigation-editor'){show(`<h2>What deserves a closer look?</h2><label>Security<select id="investigation-symbol">${editorSymbols().map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label>Your question<textarea id="investigation-reason" maxlength="500">Investigate recent developments and identify what deserves attention.</textarea></label>${btn('Investigate with Nemotron','investigation-submit')}`);return;}
if(action==='investigation-submit'){await command('investigate',{symbol:$('#investigation-symbol').value,reason:$('#investigation-reason').value});$('#modal').close();mode='live';navigate('today');return;}
if(action==='case'){await command('start',{mode:'verified',recording:id});return;}
if(action==='ask-editor'){show(`<div class="eyebrow">ASK MARKETBELL</div><h2>What do you want to know?</h2><p>I answer from what I read, did and set aside, and I quote my records. I don’t give buy or sell advice.</p><label for="ask-question">Your question</label><textarea id="ask-question" maxlength="300">Why didn’t you tell me about NVDA today?</textarea>${btn('Ask','ask-submit')}`);return;}
if(action==='ask-submit'){const question=$('#ask-question').value;$('#modal').close();const r=await command('ask',{question});notify(r?.job?'Nemotron is answering from your records. The answer appears on Today.':'Answered from your records.');return;}
if(action==='overturn'){const r=await command('quiet-overturn',{id});notify((r?.learned||'Noted.')+(r?.job?' Investigating it now.':''));return;}
if(action==='audit')return investigation(id);
if(action==='review-monitored'){await command(action,{id});mode='live';render();notify('Fresh investigation queued in your isolated workspace.');return;}
if(action==='approve'||action==='reject'||action==='acknowledge'){const v=state.events.find(e=>e.id===id);await command(action,{id,version:v.version});notify(action==='approve'?'Research note prepared and verified. No order placed.':action==='acknowledge'?'Risk acknowledged. No action authority granted.':'Rejected. Decision recorded.');return;}
if(action==='correct'){correcting=id;show(`<div class="eyebrow">TEACH MARKETBELL</div><h2>What should we learn?</h2><p>Your correction grants no authority. Nemotron proposes a scoped rule for review.</p><label for="correction">Your preference</label><textarea id="correction" maxlength="1000">${teachingText}</textarea><div class="notice">Verified Run uses a captured Nemotron interpretation of this exact example. Editing requests fresh inference when enabled. Live corrections are sent to Nebius; demo history is retained by this server. Avoid private account information.</div>${btn('Interpret preference →','propose')}`);return;}
if(action==='propose'){const text=$('#correction').value;$('#modal').close();const r=await command('correct',{id:correcting,text});if(r?.candidate)candidateDialog();else if(r?.job)notify('Nemotron is interpreting your correction. Review opens when ready.');else notify(r?.reason||'Clarification needed; no authority granted.');return;}
if(action==='save-rule'){await command(action,{id});$('#modal').close();notify('Standing rule approved. Try the next matching event.');return;}
if(action==='decline-rule'){await command(action);$('#modal').close();notify('No standing authority granted.');return;}
if(['pause','resume','revoke'].includes(action)){const r=state.rules.find(r=>r.id===id);await command(action,{id,version:r.version});notify('Rule '+action+' recorded.');return;}
if(action==='edit'){const r=state.rules.find(r=>r.id===id);show(`<h2>Edit standing limits</h2><p>Changes require your explicit approval. Scope and expiry remain visible in Preferences.</p><label>Maximum position (%)<input id="position" type="number" min="0.1" max="5" step="0.1" value="${r.max_position_pct}"></label><label>Resulting sector exposure (%)<input id="sector" type="number" min="1" max="30" value="${r.max_sector_pct}"></label>${btn('Approve updated rule','update:'+id)}`);return;}
if(action==='update'){const r=state.rules.find(r=>r.id===id),p=Number($('#position').value),s=Number($('#sector').value);await command('edit',{id,version:r.version,updates:{max_position_pct:p,max_sector_pct:s}});$('#modal').close();return;}
if(action==='restart'){show(`<h2>Start a fresh workspace?</h2><p>Your old audit is preserved. A new isolated session starts with no standing authority.</p>${btn('Start fresh','confirm-restart')}`);return;}
if(action==='confirm-restart'){await command('restart');$('#modal').close();await refresh();return;}
if(action==='retry'){await command(action,{id});return;}
}catch(error){notify(error.message);}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';if(page==='today')refresh();else render();window.scrollTo(0,0);});
let lastCandidate=null,lastListCandidate=null;
setInterval(async()=>{if(busy||$('#modal').open)return;if([...state.jobs,...state.monitored.jobs].some(j=>['queued','running'].includes(j.status))){await refresh();if(state.candidate&&state.candidate.id!==lastCandidate){lastCandidate=state.candidate.id;candidateDialog();}else if(universeData?.list_candidate&&universeData.list_candidate.id!==lastListCandidate){lastListCandidate=universeData.list_candidate.id;listCandidateDialog();}}},2500);
setInterval(()=>{if(!busy&&!$('#modal').open)refresh();},30000);
render();refresh();

document.addEventListener('change',async e=>{if(e.target.id==='impact-period'){period=Number(e.target.value);await refresh();}if(e.target.id==='impact-dataset'){dataset=e.target.value;await refresh();}});
